import socket

def port_open(host, port):
    with socket.socket() as s:
        s.settimeout(1)
        return s.connect_ex((host, port)) == 0

tests = {'local web': port_open('127.0.0.1', 8000)}
for name, passed in tests.items():
    print(('PASS' if passed else 'CHECK'), name)

import ipaddress

LAB_NETWORKS = [ipaddress.ip_network('127.0.0.0/8'), ipaddress.ip_network('192.168.56.0/24')]
def in_lab(value):
    ip = ipaddress.ip_address(value)
    return any(ip in network for network in LAB_NETWORKS)

